H.background();
const cx = H.W * 0.5, cy = H.H * 0.56, R = Math.min(H.W, H.H) * 0.30;
const w0 = P.w0, alpha = P.alpha;
// loop time so the disk doesn't spin off forever
const tt = (t % 6);
const theta = w0 * tt + 0.5 * alpha * tt * tt;   // theta = w0 t + 1/2 alpha t^2
const omega = w0 + alpha * tt;                    // omega = w0 + alpha t
// wheel rim
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
H.circle(cx, cy, R + 8, { stroke: H.colors.axis, width: 1 });
// spokes that rotate by theta
for (let k = 0; k < 6; k++) {
  const a = theta + k * H.TAU / 6;
  H.line(cx, cy, cx + R * Math.cos(a), cy - R * Math.sin(a), { color: H.colors.grid, width: 1.5 });
}
// a marker on the rim at angle theta
const mx = cx + R * Math.cos(theta), my = cy - R * Math.sin(theta);
H.line(cx, cy, mx, my, { color: H.colors.accent, width: 3 });
H.circle(mx, my, 8, { fill: H.colors.warn });
// tangential velocity arrow (perpendicular to radius), length scaled by omega
const vlen = H.clamp(Math.abs(omega) * 12, 0, R * 0.9) * Math.sign(omega || 1);
H.arrow(mx, my, mx - vlen * Math.sin(theta), my - vlen * Math.cos(theta), { color: H.colors.good, width: 3 });
H.text("Angular kinematics:  theta = omega0 t + 1/2 alpha t^2", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("t = " + tt.toFixed(2) + " s    omega = " + omega.toFixed(2) + " rad/s    theta = " + theta.toFixed(2) + " rad", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "radius", color: H.colors.accent }, { label: "v (tangential)", color: H.colors.good }], H.W - 175, 28);
